18: /** Generates the complete deterministic code-fact graph, separate from Agent views. */
19: export class StructuralGraphService {
20:   private readonly outputPath: string;
21:   private readonly previousOutputPath: string;
22:   private readonly cacheDirectory: string;
23:   private lastStatistics?: StructuralUpdateStatistics;
24: 
25:   constructor(private readonly workspaceRoot: string) {
26:     this.outputPath = path.join(
27:       workspaceRoot,
28:       '.vscode',
29:       '.knowledge',
30:       'structural-graph.json'
31:     );
32:     this.previousOutputPath = path.join(
33:       workspaceRoot,
34:       '.vscode',
35:       '.knowledge',
36:       'structural-graph.previous.json'
37:     );
38:     this.cacheDirectory = path.join(
39:       workspaceRoot,
40:       '.vscode',
41:       '.knowledge',
42:       'cache',
43:       'structural'
44:     );
45:   }
46: 
47:   public getOutputPath(): string {
48:     return this.outputPath;
49:   }
50: 
51:   public getCacheDirectory(): string {
52:     return this.cacheDirectory;
53:   }
54: 
55:   public getPreviousOutputPath(): string {
56:     return this.previousOutputPath;
57:   }
58: 
59:   public hasGraph(): boolean {
60:     return existsSync(this.outputPath);
61:   }
62: 
63:   public read(): StructuralGraphDocument {
64:     if (!this.hasGraph()) {
65:       throw new Error(
66:         'structural-graph.json does not exist. Generate the structural graph first.'
67:       );
68:     }
69:     return this.readFile(this.outputPath, 'structural graph');
70:   }
71: 
72:   public readPrevious(): StructuralGraphDocument | undefined {
73:     return existsSync(this.previousOutputPath)
74:       ? this.readFile(this.previousOutputPath, 'previous structural graph')
75:       : undefined;
76:   }
77: 
78:   public getLastStatistics(): StructuralUpdateStatistics | undefined {
79:     return this.lastStatistics;
80:   }
81: 
82:   public generate(
83:     options: GenerateStructuralGraphOptions = {}
84:   ): StructuralGraphDocument {
85:     const extractionOptions: StructuralExtractionOptions = {
86:       workspaceRoot: this.workspaceRoot,
87:       scope: options.scope,
88:       tsconfigPath: options.tsconfigPath,
89:       generatedAt: options.generatedAt,
90:     };
91:     const result = updateStructuralGraph({
92:       ...extractionOptions,
93:       outputPath: this.outputPath,
94:       cacheDirectory: this.cacheDirectory,
95:       force: options.force,
96:     });
97:     this.lastStatistics = result.statistics;
98:     return result.graph;
