175: export function formatDiff(diff: ReturnType<typeof diffStructuralGraphs>): string[] {
176:   if (!diff.available) {
177:     return ['Structural diff unavailable: no previous structurally different valid snapshot exists.'];
178:   }
179:   const lines = [
180:     `Structural diff | ${diff.baselineGeneratedAt} -> ${diff.currentGeneratedAt}`,
181:     `Summary | entities +${diff.addedEntities.length} -${diff.removedEntities.length} ~${diff.changedEntities.length} | relations +${diff.addedRelations.length} -${diff.removedRelations.length} ~${diff.changedRelations.length}`
182:   ];
183:   for (const entity of diff.addedEntities) lines.push(`+N ${entity.name} <${entity.key}> | ${entity.filePath}:${entity.startLine}`);
184:   for (const entity of diff.removedEntities) lines.push(`-N ${entity.name} <${entity.key}> | ${entity.filePath}:${entity.startLine}`);
185:   for (const change of diff.changedEntities) lines.push(`~N ${change.after.name} <${change.after.key}> | ${change.after.filePath}:${change.after.startLine}`);
186:   for (const relation of diff.addedRelations) lines.push(`+${relationLine(relation)}`);
187:   for (const relation of diff.removedRelations) lines.push(`-${relationLine(relation)}`);
188:   for (const change of diff.changedRelations) lines.push(`~R ${change.after[0]?.source ?? change.before[0]?.source} --${change.after[0]?.verb ?? change.before[0]?.verb}--> ${change.after[0]?.target ?? change.before[0]?.target}`);
189:   return lines;
